insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('25918c99-fb34-501f-a884-5de69bec90e7', public.guide_id('Angel of Death'), 'Phase 2 – Necromancy (solo basic)', $json$[{"kind":"note","id":"","note":"Phase 2 will begin as Nex hits 2.1 million health constitution and will be shortly followed by amalgamation bloodamalg spawns, which will be cleared with Invoke Death invokedeath and threads threadsoffate","phase":true},{"kind":"note","id":"","note":"The objective is to kill all 4 amalgamations simultaneously and lure all minions into the center such that scythe combo spectralscythe and threads threadsoffate will hit them all as well as Nex"},{"kind":"note","id":"","note":"In the meantime, focus on getting Nex down to 1.8 million health constitution to avoid getting another elements special attack, which will spawn blocking tiles that will prevent the minions from being lured properly"},{"kind":"ability","id":"death-skulls"},{"kind":"action","id":"target-cycle","hint":"Nex – should be centred during this phase if you phased at the beginning of the elements special attack in phase 1, otherwise make sure to recenter her so that threads threadsoffate will hit all amalgamations"},{"kind":"note","id":"","note":"Tier 90 off-hand skulllantern90: invokedeath"},{"kind":"ability","id":"threads-of-fate"},{"kind":"note","id":"","note":"(8"},{"kind":"ability","id":"weapon-special-attack","sameTick":true},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"note","id":"","note":"Tier 95 off-hand soulboundlantern: invokedeath"},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"volley-of-souls","hint":"3 stack"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"note","id":"","note":"The recommended abilities are invokedeath"},{"kind":"ability","id":"spectral-scythe","sameTick":true,"hint":"2x"},{"kind":"ability","id":"spectral-scythe","sameTick":true,"hint":"2x"},{"kind":"ability","id":"spectral-scythe","sameTick":true,"hint":"2x"},{"kind":"ability","id":"threads-of-fate","sameTick":true},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"note","id":"","note":"Use devo as minions spawn, freedom on the first set of stuns and anti as threadsoffate comes back off cooldown to prevent it from being interrupted and potentially losing a threaded volley volleyofsouls"},{"kind":"note","id":"","note":"Upkeep single target damage on Nex between spectralscythe and threadsoffate cooldowns"},{"kind":"note","id":"","note":"Blood Siphon bloodsiphon may be used for healing between spectralscythe and threadsoffate cooldowns"}]$json$::jsonb, array['Necromancy']::text[], true, to_timestamp(1788796247788 / 1000.0), to_timestamp(1788796247788 / 1000.0))
