insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('7f5f5df1-f582-5f33-a3af-79005463e412', public.guide_id('Angel of Death'), 'Phase 2 – Necromancy (duo trio basic)', $json$[{"kind":"note","id":"","note":"Phase 2 will begin as Nex hits 2.1 million health constitution and will be shortly followed by amalgamation bloodamalg spawns, which will be cleared with Invoke Death invokedeath and threads threadsoffate","phase":true},{"kind":"note","id":"","note":"Depending on team size, minion lures will differ but the objective will be to pull them into the center such that scythe combo spectralscythe and threads threadsoffate will hit them all as well as Nex"},{"kind":"note","id":"","note":"In the meantime, all players should focus on getting Nex down to 1.8 million health constitution to avoid getting another elements special attack, which will spawn blocking tiles that will prevent the minions from being lured properly"},{"kind":"ability","id":"death-skulls"},{"kind":"ability","id":"invoke-death","hint":"Duo:"},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"note","id":"","note":"Note: Replace first volleyofsouls with 8+ stack deathguard90 spec if soulboundlantern is not owned","phase":true},{"kind":"note","id":"","note":"Trio MT 1: invokedeath"},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"note","id":"","note":"The recommended abilities are invokedeath"},{"kind":"ability","id":"spectral-scythe","sameTick":true,"hint":"2x"},{"kind":"ability","id":"spectral-scythe","sameTick":true,"hint":"2x"},{"kind":"ability","id":"spectral-scythe","sameTick":true,"hint":"2x"},{"kind":"ability","id":"threads-of-fate","sameTick":true},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"invoke-death","hint":"Minion tank:"},{"kind":"ability","id":"spectral-scythe"},{"kind":"ability","id":"spectral-scythe"},{"kind":"ability","id":"spectral-scythe"},{"kind":"ability","id":"spectral-scythe","hint":"Base:"},{"kind":"ability","id":"spectral-scythe"},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"spectral-scythe"},{"kind":"note","id":"","note":"Optional: bloat the minion you want to kill first, typically U or G to avoid prolonging their respective mechanics in phase 4"},{"kind":"ability","id":"invoke-death","hint":"Base:"},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"threads-of-fate","hint":"MT 2:"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"note","id":"","note":"MT 1, who used threadsoffate on bloodamalg: focus on doing single-target damage to Nex, threadsoffate for single-target damage if it comes up before minions are finished"},{"kind":"note","id":"","note":"Minion tanks can use devo and anti to reduce damage and prevent their rotations from being disrupted"}]$json$::jsonb, array['Necromancy']::text[], true, to_timestamp(1788796247789 / 1000.0), to_timestamp(1788796247789 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('3636ae83-1f41-5e6f-a382-706dd1d49141', public.guide_id('Angel of Death'), 'Phase 1 – Necromancy (duo trio basic)', $json$[{"kind":"note","id":"","note":"In phase 1 the base will apply the defence level reduction from Statius's Warhammer swh eofspec, which will last until pillars begins"},{"kind":"ability","id":"invoke-death","hint":"Lord of Bones invokelordofbones may also be used for a slower-ramping defence reduction"},{"kind":"note","id":"","note":"One player (the base in this rotation) will use Invoke Death invokedeath and Threads of Fate threadsoffate to clear out the reavers bloodreaver, utilising the stun from Death Guard special attack deathguard90 eofspec to keep them from reaching Nex"},{"kind":"note","id":"","note":"Note that the reavers must be close enough for threads threadsoffate to reach them all, this can be timed as the reavers reach the set of green-rune tiles surrounding the center of the arena","phase":true},{"kind":"ability","id":"conjure-undead-army"},{"kind":"ability","id":"life-transfer"},{"kind":"ability","id":"command-vengeful-ghost"},{"kind":"ability","id":"split-soul","hint":"(3.0)"},{"kind":"ability","id":"command-skeleton-warrior"},{"kind":"action","id":"target-cycle"},{"kind":"spell","id":"smoke-cloud","sameTick":true},{"kind":"weapon","id":"dark-ice-shard","sameTick":true,"hint":"switch added"},{"kind":"weapon","id":"enhanced-excalibur","sameTick":true,"hint":"switch added"},{"kind":"spec","id":"obliterate","sameTick":true,"hint":"EoF"},{"kind":"weapon","id":"omni-guard","hint":"switch added"},{"kind":"weapon","id":"soulbound-lantern","sameTick":true,"hint":"switch added"},{"kind":"ability","id":"touch-of-death"},{"kind":"weapon","id":"omni-guard"},{"kind":"spec","id":"death-essence","sameTick":true},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"death-skulls"},{"kind":"ability","id":"bloat"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"command-skeleton-warrior"},{"kind":"ability","id":"touch-of-death"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"finger-of-death"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"invoke-death"},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"demon-slayer","sameTick":true},{"kind":"action","id":"target-cycle","hint":"Blood reaver – on green tiles"},{"kind":"spec","id":"death-grasp","hint":"EoF"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"touch-of-death"},{"kind":"note","id":"","note":"continue until phased"},{"kind":"ability","id":"conjure-undead-army"},{"kind":"ability","id":"life-transfer"},{"kind":"ability","id":"command-vengeful-ghost"},{"kind":"ability","id":"split-soul","hint":"(3.0)"},{"kind":"ability","id":"command-skeleton-warrior"},{"kind":"action","id":"target-cycle"},{"kind":"ability","id":"death-skulls","sameTick":true},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"touch-of-death"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"living-death"},{"kind":"special","id":"adrenaline-renewal-potion","sameTick":true},{"kind":"ability","id":"touch-of-death"},{"kind":"ability","id":"death-skulls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"finger-of-death"},{"kind":"ability","id":"command-skeleton-warrior"},{"kind":"ability","id":"death-skulls"},{"kind":"ability","id":"touch-of-death"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"finger-of-death"},{"kind":"ability","id":"volley-of-souls"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"necromancy"},{"kind":"ability","id":"death-skulls"},{"kind":"note","id":"","note":"continue until phased"},{"kind":"note","id":"","note":"Use omniguard spec if adren is available"},{"kind":"note","id":"","note":"Note: Replace omniguard spec with soul