  ('ff3b4668-988d-58c5-a543-f9922ba6594a', public.guide_id('Arch-Glacor'), 'Example Arms rotation – Necromancy (high enrage)', $json$[{"kind":"note","id":"","note":"If starting with low residualsoul soul stacks (1-2), use soulstrikeflank over volleyofsouls."},{"kind":"note","id":"","note":"Use soulsap & touchofdeath where appropriate to build adren and stacks before dumping."},{"kind":"ability","id":"bloat","hint":", deathskulls , and commandskeleton should always be used first, as their damage is dealt over time."},{"kind":"weapon","id":"roar-of-awakening"},{"kind":"spec","id":"soulfire","sameTick":true,"hint":"Offstyle soulfire"},{"kind":"weapon","id":"ode-to-deceit","sameTick":true,"hint":"spec may optionally be used after commandskeleton ."},{"kind":"weapon","id":"death-guard-tier-90","hint":"switch added"},{"kind":"weapon","id":"soulbound-lantern","sameTick":true,"hint":"switch added"},{"kind":"ability","id":"invoke-death"},{"kind":"ability","id":"soul-strike","hint":"Flank"},{"kind":"ability","id":"soul-strike","hint":"Flank"},{"kind":"ability","id":"invoke-death"},{"kind":"ability","id":"split-soul"},{"kind":"action","id":"target-cycle"},{"kind":"special","id":"vulnerability-bomb","sameTick":true},{"kind":"ability","id":"bloat","sameTick":true},{"kind":"ability","id":"death-skulls"},{"kind":"ability","id":"command-skeleton-warrior"},{"kind":"ability","id":"soul-strike","hint":"Flank, (until 0 stacks)"},{"kind":"weapon","id":"death-guard-tier-90"},{"kind":"spec","id":"death-grasp","sameTick":true,"hint":"eofspec (6/8 necrosis , use fingerofdeath"},{"kind":"weapon","id":"death-guard-tier-90"},{"kind":"spec","id":"death-grasp","sameTick":true,"hint":"eofspec if at 12/12)"},{"kind":"ability","id":"command-putrid-zombie"},{"kind":"ability","id":"command-phantom-guardian"},{"kind":"ability","id":"devotion"},{"kind":"weapon","id":"omni-guard"},{"kind":"spec","id":"death-essence","sameTick":true},{"kind":"note","id":"","note":"Note: Use devo when required.","phase":t