  ('c237d357-f7b0-5157-ac36-6561866fe5cd', public.guide_id('Vorago'), 'P4: Scopulus – Necromancy (solo)', $json$[{"kind":"note","id":"","note":"Can omit invokedeath from the pre-phase since it will be applied later in the phase"},{"kind":"note","id":"","note":"Start south so that you can tc + deathskulls and have it bounce between the south two Scopulus","phase":true},{"kind":"ability","id":"touch-of-death","hint":"second ability to be able to quickly build necrosis"},{"kind":"note","id":"","note":"Run up either east / west wall while building necrosis","hint":"Residual Soul"},{"kind":"note","id":"","note":"At 8 necrosis and 2 residualsoul: target cycle"},{"kind":"ability","id":"invoke-death","sameTick":true},{"kind":"ability","id":"threads-of-fate"},{"kind":"ability","id":"soul-sap"},{"kind":"ability","id":"volley-of-souls"},{"kind":"weapon","id":"death-guard-tier-90","hint":"switch added"},{"kind":"spec","id":"death-grasp","hint":"EoF"},{"kind":"note","id":"","note":"Scops are low health so devo can be used to get"},{"kind":"note","id":"","note":"10s from killing 2 of them","sameTick":true},{"kind":"ability","id":"bloat","hint":"is also recommended since it will spread to the other scops when one dies with bloat on it"}]$json$::jsonb, array['Necromancy']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('8c40a5cd-f849-5cf2-ad16-3b4f8448d487', public.guide_id('Vorago'), 'Phase 3 - Phase 8 Overview – Necromancy (solo)', $json$[{"kind":"ability","id":"conjure-undead-army"},{"kind":"ability","id":"invoke-death"},{"kind":"ability","id":"command-vengeful-ghost"},{"kind":"ability","id":"invoke-lord-of-bones"},{"kind":"ability","id":"command-skeleton-warrior"},{"kind":"note","id":"","note":"Aim to also re-set reaverpouch autofire to 1 during each pre-phase"}]$json$::jsonb, array['Necromancy']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('a7fb1db0-a69f-51d8-a42d-1818220513be', public.guide_id('Vorago'), 'Mauling – Magic (duo)', $json$[{"kind":"note","id":"","note":"You should always wait with mauling until the start of a Reflect reflect in order to optimise your Phase 11 start."},{"kind":"note","id":"","note":"Shield Dome cannot be used off GCD (you have to wait for your GCD to be over, then Shield Dome"},{"kind":"note","id":"","note":"Maul)."},{"kind":"note","id":"","note":"The player not mauling should reapply the SWH swh spec and place a combat dummy dummy in the very east."},{"kind":"note","id":"","note":"During the phase transition, both players build up to 100% on the dummy dummy (use defensive abilities"},{"kind":"ability","id":"necromancy","sameTick":true,"hint":"attacks)."}]$json$::jsonb, array['Necromancy']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('2e1313f1-5cff-5fef-a8bf-fa686f1e67ec', public.guide_id('Vorago'), 'Bomb Tank – Magic (duo)', $json$[{"kind":"note","id":"","note":"After each Waterfall, keep Vorago voked voke until Bleeds."},{"kind":"note","id":"","note":"Devotion devo for yourself (do not Intercept Cept) the fourth Blue Bomb (first Blue Bomb after the Stone Clone's spawn)."},{"kind":"note","id":"","note":"Take bleeds 1 and 2 (freedom"},{"kind":"ability","id":"escape"}]$json$::jsonb, array['Ranged']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('e135b8c2-b6be-5937-a123-9c236a78ba41', public.guide_id('Vorago'), 'Base Tank – Magic (duo)', $json$[{"kind":"note","id":"","note":"After each Waterfall, surge surge under Vorago and step under."},{"kind":"note","id":"","note":"If not skipping the Stone Clone, use Anticipation anti or Freedom freedom before the clone's spawn."},{"kind":"note","id":"","note":"After each Team Split, Barricade Intercept cade Cept."},{"kind":"ability","id":"provoke","hint":"voke for bleeds 3, 4 and 5 (freedom"},{"kind":"ability","id":"escape"},{"kind":"ability","id":"bladed-dive","sameTick":true},{"kind":"ability","id":"escape"},{"kind":"note","id":"","note":"Use Devotion devo for yourself during Reflect reflect (do no Intercept Cept)."}]$json$::jsonb, array['Ranged', 'Melee']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('9af89e7a-2608-5bb3-ac1b-b0fc57dab60a', public.guide_id('Vorago'), 'Bring Him Down – Magic (duo)', $json$[{"kind":"weapon","id":"seren-godbow","hint":"switch added"},{"kind":"ability","id":"ranged","hint":"range"},{"kind":"weapon","id":"seren-godbow"},{"kind":"spec","id":"crystal-rain","sameTick":true},{"kind":"ability","id":"snipe"},{"kind":"ability","id":"greater-ricochet"},{"kind":"ability","id":"magic","hint":"Mage"},{"kind":"spell","id":"blood-barrage","hint":"wm"},{"kind":"ability","id":"dragon-breath"},{"kind":"spell","id":"blood-barrage","hint":"asphyx"},{"kind":"note","id":"","note":"Note: If both players use magic, Shatter Shatter should be utilised for consistently passing the damage check.","phase":true}]$json$::jsonb, array['Ranged', 'Magic']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
insert into public.rotations (id, owner_id, name, steps, styles, is_public, created_at, updated_at) values
  ('c84ef048-27be-5704-a3a1-b4e869c10296', public.guide_id('Vorago'), 'P5 Purple Bomb - Rotation rationale – Necromancy (introdu…', $json$[{"kind":"note","id":"","note":"The first five abilities are used immediately on drop-down before Vorago spawns","phase":true},{"kind":"ability","id":"soul-sap","sameTick":true,"hint":"first just allows you to get to 5 soul stacks prior to livingdeath"},{"kind":"note","id":"","note":"The first Vorago auto is blocked by the disrupt cast during waterfall p4. The cadeturtling should occur right before the second blue bomb hits you and hopefully will last through reflect which gets you to livingdeath"},{"kind":"note","id":"","note":"If deathskulls crit though, you will likely generate enough stall that the last 1-2 autos of Vorago will not be under cade"},{"kind":"note","id":"","note":"Hence the commandskeleton and livingdeath at the end of reflect."},{"kind":"note","id":"","note":"Once you get to livingdeath, a simple rotation follows which should generate more than enough push."},{"kind":"note","id":"","note":"Depending on push, after the second fingerofdeath you might be able to just use volleyofsouls"},{"kind":"spell","id":"disruption-shield","sameTick":true},{"kind":"weapon","id":"omni-guard"},{"kind":"spec","id":"death-essence","sameTick":true},{"kind":"ability","id":"necromancy"},{"kind":"spec","id":"death-grasp","hint":"EoF"},{"kind":"note","id":"","note":"maul","sameTick":true},{"kind":"note","id":"","note":"Note: ingen is written into the example rotations, but is not necessary at all. It will just bring you from ~87% to 100% hit chance on that first deathskulls","phase":true}]$json$::jsonb, array['Necromancy']::text[], true, to_timestamp(1788796247780 / 1000.0), to_timestamp(1788796247780 / 1000.0))
